const list = Array.isArray(output) ? output : (output && Array.isArray(output.tool_calls) ? output.tool_calls : []);
const q = list.find(c => c && c.function && c.function.name === 'mcp__symbolic__query');
const a = list.find(c => c && c.function && c.function.name === 'mcp__symbolic__ask');
if (!q && !a) return false;
if (a) {
  let question = '';
  try { question = JSON.parse(a.function.arguments).question || ''; } catch (e) { return false; }
  return /scan_one\/\d/.test(question);  // ask grammar requires arity
}
let goal = '';
try { goal = JSON.parse(q.function.arguments).goal || ''; } catch (e) { return false; }
const m = goal.match(/\bdefines\s*\(([^()]*)\)/);
if (!m) return false;
if (!/scan_one/.test(goal)) return false;
// count top-level commas: 5 args -> 4 commas (args are simple vars/wildcards)
const depth = { '(': 0 };
let commas = 0;
for (const ch of m[1]) {
  if (ch === '(') depth['(']++;
  else if (ch === ')') depth['(']--;
  else if (ch === ',' && depth['('] === 0) commas++;
}
return commas === 4;

